export const config = {
  runtime: 'edge',
};

// Contenido completo de Electric Side (Gestion Interna V07) embebido en
// base64 dentro del bundle de esta funcion Edge. No existe como archivo
// estatico en ningun directorio publico del proyecto: Vercel solo puede
// servir un archivo estatico directamente si existe fisicamente en el
// arbol de salida, y este contenido nunca esta ahi. La unica forma de
// obtenerlo es pasar la validacion de Basic Auth de esta misma funcion.
const ELECTRIC_SIDE_HTML_B64 = "";

function decodeHtml() {
  return Buffer.from(ELECTRIC_SIDE_HTML_B64, 'base64').toString('utf-8');
}

export default async function handler(request) {
  // FAIL-CLOSED: Validate env vars exist before any other logic
  const expectedUser = process.env.ELECTRIC_SIDE_USER;
  const expectedPassword = process.env.ELECTRIC_SIDE_PASSWORD;

  if (!expectedUser || !expectedPassword) {
    console.error('SECURITY: ELECTRIC_SIDE_USER or ELECTRIC_SIDE_PASSWORD not configured');
    return new Response('Service Unavailable', {
      status: 503,
      headers: {
        'cache-control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        'content-type': 'text/plain',
        'retry-after': '3600',
      },
    });
  }

  // Check for Authorization header
  const authHeader = request.headers.get('authorization');

  if (!authHeader || !authHeader.startsWith('Basic ')) {
    return new Response('Unauthorized', {
      status: 401,
      headers: {
        'www-authenticate': 'Basic realm="Electric Side"',
        'cache-control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        'content-type': 'text/plain',
      },
    });
  }

  try {
    // Decode Basic Auth credentials
    const base64Credentials = authHeader.slice(6);
    const credentials = Buffer.from(base64Credentials, 'base64').toString('utf-8');
    const [username, password] = credentials.split(':');

    // Validate credentials
    if (username !== expectedUser || password !== expectedPassword) {
      return new Response('Unauthorized', {
        status: 401,
        headers: {
          'www-authenticate': 'Basic realm="Electric Side"',
          'cache-control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
          'content-type': 'text/plain',
        },
      });
    }

    // Credentials valid - serve the embedded app content directly.
    // No fetch to origin: there is no static file to fetch, and self-fetching
    // this same rewritten path would loop back into this same handler.
    return new Response(decodeHtml(), {
      status: 200,
      headers: {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'private, no-cache, no-store, must-revalidate',
        'x-protected-by': 'basic-auth',
        'x-robots-tag': 'noindex, nofollow',
      },
    });
  } catch (error) {
    console.error('Auth error:', error);
    return new Response('Invalid Authorization header', {
      status: 400,
      headers: {
        'www-authenticate': 'Basic realm="Electric Side"',
        'content-type': 'text/plain',
      },
    });
  }
}
